/**
 * O formato das conchas — porte de `componentes/viz/concha.js`.
 *
 * A concha cresce numa espiral LOGARÍTMICA (equiangular), r = a·e^(b·θ). O que o
 * investigador controla é o `b`: o quanto o raio multiplica a cada radiano.
 * Pequeno demais e a espiral aperta até virar um círculo; grande demais e ela
 * abre até deixar de ser concha. No valor certo nasce a curva do náutilo — a que
 * mantém a MESMA FORMA enquanto cresce, que é o ponto do módulo.
 *
 * As paredes das câmaras (um raio a cada meia volta) são o que faz a curva ler
 * como concha em corte, e não como um rabisco em espiral.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const VOLTAS = 4;
const PASSO = 0.08;
const THETA_MAX = VOLTAS * 2 * Math.PI;

const concha: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    // O controle é percentual por volta; a espiral pede o fator por radiano.
    const bPct = Math.max(0, numeroDe(valores, 'b', 0));
    const b = bPct / 100;
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A espiral que cresce sem mudar de forma');

    const cx = L * 0.52;
    const cy = A * 0.54;

    // A espiral cresce sem limite; a escala amarra o raio final ao espaço que há.
    const raioMaximo = Math.exp(b * THETA_MAX);
    const escala = (Math.min(L, A) * 0.38) / (raioMaximo || 1);

    const ponto = (theta: number): readonly [number, number] => {
      const r = escala * Math.exp(b * theta);
      // `-theta` para a espiral abrir no sentido horário, como a concha em corte.
      return [cx + Math.cos(-theta) * r, cy + Math.sin(-theta) * r];
    };

    const tinta = ok ? cor.verde : cor.azul;

    // Miolo da última câmara — o lábio da concha, a parte viva do animal.
    ctx.fillStyle = ok ? 'rgb(47 143 92 / 18%)' : 'rgb(60 74 158 / 14%)';
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    for (let th = THETA_MAX - Math.PI / 2; th <= THETA_MAX; th += PASSO) {
      const [x, y] = ponto(th);
      ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();

    // Paredes das câmaras: um raio a cada meia volta.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    for (let th = Math.PI; th <= THETA_MAX; th += Math.PI / 2) {
      const [x, y] = ponto(th);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(x, y);
      ctx.stroke();
    }

    // A curva.
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 2.6;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let th = 0; th <= THETA_MAX; th += PASSO) {
      const [x, y] = ponto(th);
      if (th === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    texto(
      ctx,
      `fator ${bPct.toString().replace('.', ',')}% por volta`,
      L / 2,
      A * 0.87,
      limitar(A * 0.044, 10, 14),
      {
        cor: cor.fraco,
        peso: 700,
      },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Espiral logarítmica: a forma se conserva ao crescer ✔',
      bPct < 12
        ? 'Apertada demais — quase um círculo.'
        : bPct > 24
          ? 'Aberta demais — perde a forma da concha.'
          : 'Ajuste o fator de crescimento.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default concha;
